export function getAutonomousThoughtAndDecision(npc: CommunityNPCState): {
  ownThought: string;
  currentDecision: string;
} {
  if (npc.inTrain) {
    return {
      ownThought: 'চিন্তা: মেট্রো ট্রেনে চড়ে ম্যাপের চারপাশ দিয়ে দ্রুত গন্তব্যে যাচ্ছি!',
      currentDecision: 'সিদ্ধান্ত: পরবর্তী স্টেশনে ট্রেন থামলে প্ল্যাটফর্মে নামবো',
    };
  }
  if (npc.ridingVehicleId === 'car-bus') {
    return {
      ownThought: 'চিন্তা: লোকাল বাসে সিট পেয়েছি, পরের স্টপেজে নামবো!',
      currentDecision: 'সিদ্ধান্ত: বাস স্টপে বাস থামলে নেমে কাজে যাবো',
    };
  }
  if (npc.behavior === 'WORK_GARMENTS' || npc.role === 'GARMENT_WORKER') {
    return {
      ownThought: 'চিন্তা: আজ গার্মেন্টসের এক্সপোর্ট শার্ট ও সোয়েটারের টার্গেট পূরণ করতে হবে!',
      currentDecision: 'সিদ্ধান্ত: সেলাই মেশিন ও কাটিং টেবিলে মনোযোগ দিয়ে কাজ করছি',
    };
  }
  if (
    npc.behavior === 'WORK_OFFICE_COURT' ||
    npc.role === 'LAWYER' ||
    npc.role === 'JUDGE' ||
    npc.role === 'OFFICE_EXECUTIVE'
  ) {
    return {
      ownThought: 'চিন্তা: জজ কোর্টের মামলা ও অফিসের জরুরি ফাইলগুলো আজই নিষ্পত্তি করা দরকার!',
      currentDecision: 'সিদ্ধান্ত: এজলাস ও অফিসের কম্পিউটার ডেস্কে বসে দায়িত্ব পালন করছি',
    };
  }
  if (npc.behavior === 'WAIT_BUS') {
    return {
      ownThought: 'চিন্তা: রাস্তায় অনেক দূর হাঁটার চেয়ে বাসে করে যাওয়াই ভালো হবে!',
      currentDecision: 'সিদ্ধান্ত: বাস স্টপে দাঁড়িয়ে আছি, বাস এলেই উঠে পড়বো',
    };
  }
  if (npc.behavior === 'WAIT_TRAIN') {
    return {
      ownThought: 'চিন্তা: মেট্রো ট্রেনে জ্যাম ছাড়াই ম্যাপের চারপাশ ঘুরে যাওয়া যায়!',
      currentDecision: 'সিদ্ধান্ত: রেল স্টেশনের প্ল্যাটফর্মে দাঁড়িয়ে ট্রেনের অপেক্ষা করছি',
    };
  }
  if (npc.role === 'COP') {
    return {
      ownThought: 'চিন্তা: শহরে কেউ অপরাধ বা ছিনতাই করছে কি না কড়া নজর রাখতে হবে!',
      currentDecision: 'সিদ্ধান্ত: থানা ও রাজপথে আইন-শৃঙ্খলা পাহারা দিচ্ছি',
    };
  }
  if (npc.role === 'CLUB_DANCER') {
    return {
      ownThought: 'চিন্তা: আজ নাইট ক্লাবে নতুন গানের তালে সবাইকে নাচাতে হবে!',
      currentDecision: 'সিদ্ধান্ত: ডিস্কো ফ্লোরে গান গাইছি ও নাচছি',
    };
  }
  if (npc.role === 'FOOTBALLER') {
    return {
      ownThought: 'চিন্তা: বল পেলেই গোলপোস্টের কোণায় জোরালো শট নেবো!',
      currentDecision: 'সিদ্ধান্ত: স্টেডিয়ামের মাঠে ফুটবল ম্যাচ খেলছি',
    };
  }
  if (npc.role === 'HOTEL_CHEF' || npc.role === 'MUDI_SHOPKEEPER' || npc.role === 'SHOPKEEPER' || npc.role === 'VAN_VENDOR') {
    return {
      ownThought: 'চিন্তা: ক্রেতাদের সেরা মানের খাবার ও সদাই দিলে ব্যবসা আরও বাড়বে!',
      currentDecision: 'সিদ্ধান্ত: দোকানে ক্রেতাদের সেবা দিচ্ছি ও ক্যাশ সামলাচ্ছি',
    };
  }
  return {
    ownThought: 'চিন্তা: শহরের পরিস্থিতি দেখে নিজের পরবর্তী কাজের সিদ্ধান্ত নিচ্ছি',
    currentDecision: 'সিদ্ধান্ত: নিরাপদে শহরের রাস্তায় চলাফেরা ও কাজ করছি',
  };
}

export function createInitialCommunityNPCs(): CommunityNPCState[] {
  return createRawInitialCommunityNPCs().map((npc, idx) => {
    const wealth = getNpcDefaultWealth(npc.id, npc.role);
    const brain = getAutonomousThoughtAndDecision(npc);
    return {
      ...npc,
      money: npc.money ?? wealth.money,
      wealthLabel: npc.wealthLabel ?? wealth.wealthLabel,
      ownThought: npc.ownThought ?? brain.ownThought,
      currentDecision: npc.currentDecision ?? brain.currentDecision,
      hunger: 20 + ((idx * 17) % 50),
      energy: 75 + ((idx * 13) % 25),
      workProgress: (idx * 23) % 100,
      rideTimer: 0,
      decisionTimer: 8 + (idx % 7),
    };
  });
}

export function pickRandomLine(lines: string[]): string {
  if (!lines || lines.length === 0) return '';
  return lines[Math.floor(Math.random() * lines.length)];
}

/**
 * Triggers Dhaka Community Mob Justice (গণধোলাই) + Police Car Pursuit with Siren!
 */
export function triggerCommunityCrimeReaction(
  victim: CommunityNPCState,
  player: PlayerState,
  allNpcs: CommunityNPCState[],
  vehicles: VehicleState[]
): { isHeroicAction: boolean; mobCount: number; announcement: string; policeReward: number } {
  // Case 1: Player beat up a Chandabaj (Extortionist) OR Street Criminal (মলম পার্টি / ছিনতাইকারী)!
  // Police & Community cheer and award a handsome Police Bounty!
  if (victim.role === 'CHANDABAJ' || victim.role === 'STREET_CRIMINAL') {
    player.popularity = Math.min(100, (player.popularity || 50) + 12);
    const policeReward = victim.role === 'STREET_CRIMINAL' ? 1800 : 1500;
    let cheerCount = 0;
    for (const witness of allNpcs) {
      if (witness.id === victim.id || witness.hp <= 0) continue;
      if (witness.role === 'CHANDABAJ' || witness.role === 'STREET_CRIMINAL') {
        witness.mood = 'Angry';
        witness.behavior = 'AGGRO';
        witness.behaviorTimer = 14;
        witness.speech = 'ওই! আমাদের ওস্তাদের গায়ে হাত দিয়েছিস?! তোরে আজকে মলম লাগাই দিমু!';
        witness.speechTimer = 5;
        continue;
      }
      const d = Math.hypot(witness.x - player.x, witness.y - player.y);
      if (d < 680) {
        cheerCount++;
        witness.mood = 'Happy';
        witness.speech =
          witness.role === 'COP'
            ? `সাবাশ নাগরিক! অপরাধী ${victim.bengaliName.split(' ')[0]}-কে ধরতে পুলিশকে সাহায্য করায় আপনাকে ৳${policeReward} টাকা পুরস্কার দেওয়া হলো!`
            : witness.speaksEnglishOnly
              ? `Bravo! You helped the police stop that criminal! The whole community stands with you!`
              : `সাবাশ ভাই! অপরাধী ${victim.bengaliName.split(' ')[0]}-কে উচিত শিক্ষা দিয়েছেন! পুলিশ খুশি হয়ে আপনাকে টাকা পুরস্কার দিয়েছে!`;
        witness.speechTimer = 5.5;
        witness.analysis.trustScore = Math.min(100, witness.analysis.trustScore + 20);
        witness.analysis.emotionEmoji = '🤩';
        witness.analysis.emotionLabel = 'আনন্দিত ও গর্বিত (Proud of Hero)';
        witness.analysis.playerAssessment = 'জনতার নায়ক ও পুলিশের বন্ধু (Hero)';
      }
    }
    return {
      isHeroicAction: true,
      mobCount: cheerCount,
      policeReward,
      announcement: `👮‍♂️ সাবাশ! অপরাধী দমনে পুলিশকে সাহায্য করায় আপনি ৳${policeReward} টাকা পুরস্কার পেয়েছেন ও জনসমর্থন বেড়ে ${player.popularity}% হয়েছে!`,
    };
  }

  // Case 2: Player attacked an innocent citizen!
  // Trigger Dhaka Mob Justice + Police Car Siren Pursuit!
  player.popularity = Math.max(0, (player.popularity || 50) - 18);
  let mobCount = 0;
  const mobShouts = [
    'ধর ধর! মহল্লায় নিরীহ মানুষ মারছে! সবাই একসাথে ঘিরে ধর ওকে!',
    'সন্ত্রাসী হামলা করেছে! এলাকাবাসী ও পুলিশ গাড়ি নিয়ে ধাওয়া কর!',
    'কাউকে ছাড় দেওয়া হবে না! সবাই মিলে ওকে গণধোলাই দে!',
    'ওই দেখো মানুষ মারছে! সবাই একসাথে ওকে তাড়া কর!',
  ];
  const englishMobShouts = [
    'Stop right there! Everybody unite and chase down this street attacker!',
    'Police and citizens, surround this troublemaker immediately!',
    'Nobody attacks innocent people in our city! Chase him down!',
  ];

  // Activate Police Car Siren Pursuit!
  const policeCar = vehicles.find((v) => v.id === 'car-police');
  if (policeCar) {
    policeCar.sirenOn = true;
  }

  for (const citizen of allNpcs) {
    if (citizen.id === victim.id || citizen.hp <= 0) continue;
    if (citizen.role === 'CHANDABAJ') continue;

    // Keep Sgt. Diaz inside the Police Van so he chases the criminal with the Police Car & Siren!
    if (citizen.id === 'diaz' && citizen.drivingVehicleId === 'car-police') {
      mobCount++;
      citizen.mood = 'Angry';
      citizen.behaviorTimer = 22;
      citizen.speech = 'উই-উই-উই! ডিএমপি পুলিশ ভ্যান অপরাধীকে ধাওয়া করছে! গাড়ি থামাও বলছি!';
      citizen.speechTimer = 6;
      citizen.analysis.threatLevel = 100;
      citizen.analysis.emotionEmoji = '🚨';
      citizen.analysis.emotionLabel = 'পুলিশ ভ্যান নিয়ে ধাওয়া করছে! (Police Car Chase)';
      continue;
    }

    const dist = Math.hypot(citizen.x - player.x, citizen.y - player.y);
    if (dist < 780) {
      mobCount++;
      if (!citizen.drivingVehicleId && !citizen.ridingVehicleId && !citizen.inTrain) {
        citizen.mood = 'Angry';
        citizen.behavior = citizen.role === 'COP' ? 'PURSUIT' : 'MOB_CHASE';
        citizen.behaviorTimer = 18;
        citizen.speech = citizen.speaksEnglishOnly
          ? englishMobShouts[mobCount % englishMobShouts.length]
          : mobShouts[mobCount % mobShouts.length];
        citizen.speechTimer = 5.5;
        citizen.analysis.threatLevel = 100;
        citizen.analysis.trustScore = Math.max(0, citizen.analysis.trustScore - 45);
        citizen.analysis.emotionEmoji = '😡';
        citizen.analysis.emotionLabel = 'ক্ষুব্ধ ও প্রতিবাদী (Furious Mob)';
        citizen.analysis.playerAssessment = 'গণশত্রু ও হামলাকারী (Public Enemy - Mob Target)';
        citizen.analysis.currentGoal = 'জনতার সাথে একজোট হয়ে হামলাকারীকে ধাওয়া করছে!';
      }
    }
  }

  return {
    isHeroicAction: false,
    mobCount,
    policeReward: 0,
    announcement: `সতর্কতা! অপরাধ করায় পুলিশের গাড়ি সাইরেন বাজিয়ে এবং ${mobCount} জন এলাকাবাসী একজোট হয়ে আপনাকে ধাওয়া করছে!`,
  };
}

/**
 * 100% Self-Contained Local Automatic Analyzing System with Human Emotions & Daily Routines
 */
export function updateLocalNPCAnalysis(
  npc: CommunityNPCState,
  player: PlayerState,
  allNpcs: CommunityNPCState[],
  distToPlayer: number
) {
  let threat = npc.timesAttackedByPlayer * 30;
  if (player.punchTimer > 0 && distToPlayer < 160) threat += 35;
  if (player.inVehicleId && distToPlayer < 190) threat += 15;
  if (
    npc.behavior === 'AGGRO' ||
    npc.behavior === 'PURSUIT' ||
    npc.behavior === 'MOB_CHASE'
  ) {
    threat = Math.max(threat, 88);
  }
  if (npc.behavior === 'PANIC_FLEE') threat = Math.max(threat, 90);
  if (npc.role === 'CHANDABAJ') threat = Math.max(threat, 60);
  threat = Math.max(0, Math.min(100, threat));

  let trust =
    (player.popularity || 50) +
    npc.timesChattedWithPlayer * 10 -
    npc.timesAttackedByPlayer * 35;
  if (npc.role === 'CHANDABAJ') {
    trust = Math.max(10, 40 - (player.popularity || 50) / 2);
  } else if (
    npc.role === 'VAN_VENDOR' ||
    npc.role === 'SHOPKEEPER' ||
    npc.role === 'MEDIC' ||
    npc.role === 'RICKSHAW_PULLER' ||
    npc.role === 'BUS_CONDUCTOR'
  ) {
    trust += 15;
  }
  trust = Math.max(0, Math.min(100, Math.round(trust)));

  // Determine realistic human emotion emoji & feeling
  let emotionEmoji = npc.isFemale ? '👩' : '🙂';
  let emotionLabel = npc.speaksEnglishOnly
    ? 'Calm & Friendly (Speaks English)'
    : 'স্বাভাবিক ও শান্ত (Calm)';
  if (npc.behavior === 'MOB_CHASE' || npc.behavior === 'PURSUIT' || npc.behavior === 'AGGRO') {
    emotionEmoji = '😡';
    emotionLabel = npc.speaksEnglishOnly ? 'Furious & Indignant' : 'প্রচণ্ড ক্ষুব্ধ ও প্রতিবাদী (Furious)';
  } else if (npc.behavior === 'PANIC_FLEE' || npc.mood === 'Scared') {
    emotionEmoji = '😨';
    emotionLabel = npc.speaksEnglishOnly ? 'Terrified & Alert' : 'আতঙ্কিত ও ভীত (Terrified)';
  } else if (npc.ridingVehicleId) {
    emotionEmoji = '😄';
    emotionLabel = npc.speaksEnglishOnly ? 'Enjoying the Ride (English)' : 'আনন্দিত সহযাত্রী (Enjoying Ride)';
  } else if (npc.inTrain) {
    emotionEmoji = '🚆';
    emotionLabel = 'ট্রেন ভ্রমণে পুলকিত (Riding Metro Train)';
  } else if (npc.role === 'BUS_CONDUCTOR') {
    emotionEmoji = '📢';
    emotionLabel = 'হাঁকডাকে ব্যস্ত (Calling Gulshan-Jatrabari)';
  } else if (npc.role === 'RICKSHAW_PULLER') {
    emotionEmoji = '🛺';
    emotionLabel = 'পরিশ্রমী ও হাসিখুশি (Hardworking)';
  } else if (npc.role === 'CHANDABAJ') {
    emotionEmoji = '😠';
    emotionLabel = 'উগ্র ও দাপুটে (Intimidating)';
  } else if (trust >= 80) {
    emotionEmoji = npc.isFemale ? '👩‍💼' : '😊';
    emotionLabel = npc.speaksEnglishOnly
      ? 'Happy & Trusting (Speaks English)'
      : 'আনন্দিত ও বন্ধুসুলভ (Happy & Trusting)';
  }

  let assessment = npc.speaksEnglishOnly
    ? 'Friendly Citizen (Always Speaks English)'
    : 'শান্তিপূর্ণ ঢাকাবাসী (Peaceful Citizen)';
  if (npc.behavior === 'MOB_CHASE') {
    assessment = 'গণধোলাই টার্গেট! সবাই মিলে ধাওয়া করছে!';
  } else if (npc.ridingVehicleId && npc.ridingVehicleId === player.inVehicleId) {
    assessment = 'আপনার গাড়ির সহযাত্রী (Co-Passenger with You)';
  } else if (npc.role === 'CHANDABAJ' && threat < 75) {
    assessment = 'চাঁদা আদায়ের টার্গেট খুঁজছে (Extortion Target)';
  } else if (threat >= 75) {
    assessment = 'বিপজ্জনক আক্রমণকারী! (High-Threat Hostile)';
  } else if (player.inTrain) {
    assessment = 'কমলাপুর ট্রেনে ভ্রমণ করছে (Riding Train)';
  } else if (player.inVehicleId) {
    assessment = 'গাড়ি/বাইক চালিয়ে ঢাকায় ঘুরছে (Driving Vehicle)';
  } else if (player.hp < 55) {
    assessment = 'আহত অবস্থায় আছে, সাহায্য প্রয়োজন (Needs Medical Aid)';
  } else if ((player.popularity || 50) >= 75) {
    assessment = 'জনপ্রিয় জননেতা ও চাঁদাবাজ দমনকারী (Hero of Dhaka)';
  } else if (trust >= 75) {
    assessment = 'বিশ্বস্ত বন্ধু ও প্রতিবেশী (Trusted Friend - Will Ride With You)';
  }

  let nearestOther: CommunityNPCState | null = null;
  let minOtherDist = 140;
  for (const other of allNpcs) {
    if (other.id === npc.id || other.hp <= 0) continue;
    const d = Math.hypot(other.x - npc.x, other.y - npc.y);
    if (d < minOtherDist) {
      minOtherDist = d;
      nearestOther = other;
    }
  }

  let goal = npc.analysis.dailyActivity || 'নিজের দৈনন্দিন কাজ করছে';
  if (npc.behavior === 'MOB_CHASE') {
    goal = 'এলাকাবাসীর সাথে একজোট হয়ে অপরাধীকে ধাওয়া করছে!';
  } else if (npc.ridingVehicleId) {
    goal = 'গাড়ির দ্বিতীয় সিটে বসে একসাথে শহর ঘুরছে (2-Person Ride)';
  } else if (npc.inTrain) {
    goal = 'কমলাপুর মেট্রো ট্রেনে চড়ে যাতায়াত করছে';
  } else if (npc.behavior === 'MICHIL_RALLY') {
    goal = 'রাজপথে ব্যানার নিয়ে মিছিল ও স্লোগান দিচ্ছে';
  } else if (npc.behavior === 'MEETING_SPEECH') {
    goal = 'শাহবাগ জনসভা মঞ্চে ভাষণ দিচ্ছে';
  } else if (npc.behavior === 'EXTORTION') {
    goal = 'ফুটপাতের দোকানে ঘুরে চাঁদাবাজি করছে';
  } else if (npc.behavior === 'DRIVING') {
    goal =
      npc.role === 'BUS_CONDUCTOR'
        ? 'গুলশান-ফার্মগেট-যাত্রাবাড়ী বাস চালাচ্ছে ও যাত্রী ডাকছে'
        : 'ঢাকার রাস্তায় গাড়ি/রিকশা চালাচ্ছে';
  } else if (nearestOther) {
    goal = npc.speaksEnglishOnly
      ? `Chatting in English with ${nearestOther.name}`
      : `${nearestOther.bengaliName.split(' ')[0]}-এর সাথে দৈনন্দিন কুশল বিনিময় করছে`;
  }

  if (npc.behavior === 'WORK_GARMENTS') {
    goal = 'গার্মেন্টস ফ্যাক্টরিতে সেলাই মেশিন ও কাটিং টেবিলে কাজ করছে';
  } else if (npc.behavior === 'WORK_OFFICE_COURT') {
    goal = 'অফিস-আদালতের এজলাস ও কম্পিউটার ডেস্কে কাজ করছে';
  } else if (npc.behavior === 'WAIT_BUS') {
    goal = 'বাস স্টপে দাঁড়িয়ে বাসের জন্য অপেক্ষা করছে (বাস এলেই উঠবে)';
  } else if (npc.behavior === 'WAIT_TRAIN') {
    goal = 'রেল স্টেশনে দাঁড়িয়ে ট্রেনের জন্য অপেক্ষা করছে (ট্রেন এলেই উঠবে)';
  }

  const brain = getAutonomousThoughtAndDecision(npc);
  npc.ownThought = npc.ownThought || brain.ownThought;
  npc.currentDecision = npc.currentDecision || brain.currentDecision;

  npc.analysis = {
    threatLevel: threat,
    trustScore: trust,
    emotionEmoji,
    emotionLabel,
    dailyActivity: npc.analysis.dailyActivity || goal,
    playerAssessment: assessment,
    currentGoal: goal,
    socialTargetName: nearestOther ? nearestOther.name : null,
  };
}

/**
 * 100% Self-Contained Local Conversational AI Engine
 */
export function generateLocalConversationReply(
  npc: CommunityNPCState,
  player: PlayerState,
  rawMessage: string
): {
  speech: string;
  mood: CharacterMood;
  behavior: CommunityNPCState['behavior'];
  healedHp: number;
  popularityDelta: number;
  triggerMob: boolean;
  grantRidePermission: boolean;
  analysisNote: string;
} {
  const msg = rawMessage.trim().toLowerCase();
  // Female characters with speaksEnglishOnly ALWAYS reply in English even if player types in Bengali!
  const useBengali = npc.speaksEnglishOnly ? false : /[\u0980-\u09FF]/.test(rawMessage);
  const bank = NPC_DIALOGUE_BANKS[npc.id] || NPC_DIALOGUE_BANKS.viper;

  npc.timesChattedWithPlayer += 1;

  const isApology =
    /সরি|ক্ষমা|মাফ|ভুল|sorry|forgive|apolog|peace|truce|my bad/.test(msg);
  const isRideInviteOrRequest =
    /উঠো|উঠেন|বসো|বসেন|গাড়িতে আসো|লিফট|যাবেন|সিট|চলো ঘুরি|ride|hop in|sit|passenger|lift|come with me/.test(
      msg
    );
  const isSloganOrPolitics =
    /মিছিল|স্লোগান|নেতা|রাজনীতি|জয় জনতার|চাঁদাবাজ নিপাত|আন্দোলন|মিটিং|জনসভা|rally|slogan|politics|protest|leader/.test(
      msg
    );
  const isExtortionDemand =
    /চাঁদা দে|টাকা দে|চান্দা দে|পকেট খালি|extort|give money|pay toll/.test(msg);
  const isThreat =
    /মারব|মেরে|খুন|ধ্বংস|পালা|ফাটাব|হাত তুল|kill|fight|punch|die|destroy|beat|attack|idiot|stupid/.test(
      msg
    );
  const isTradeOrFood =
    /খাবার|ফুচকা|চটপটি|চা|সিঙ্গারা|ডাব|বিরিয়ানি|কাচ্চি|কাবাব|কিনব|দাও|দাম|হেলথ|চিকিৎসা|ডাক্তার|নার্স|বাজার|শপিং|সবজি|মাছ|কাপড়|ঘড়ি|ভিক্ষা|সাহায্য|দান|টাকা নাও|food|buy|eat|tea|drink|heal|help|snack|price|water|shop|market|charity|alms/.test(
      msg
    );
  const isCityQuestion =
    /কোথায়|এলাকা|শহর|ঢাকা|ট্রেন|গাড়ি|বাস|গুলশান|যাত্রাবাড়ী|রিকশা|সিএনজি|পার্ক|নদী|কে তুমি|পরিচয়|খবর কী|কী কাজ|where|who|city|dhaka|train|bus|car|park|what/.test(
      msg
    );

  if (isApology) {
    npc.timesAttackedByPlayer = 0;
    const nextBehavior = npc.drivingVehicleId
      ? 'DRIVING'
      : npc.role === 'POLITICAL_LEADER'
        ? 'MEETING_SPEECH'
        : npc.role === 'ACTIVIST'
          ? 'MICHIL_RALLY'
          : npc.role === 'CHANDABAJ'
            ? 'EXTORTION'
            : npc.role === 'BEGGAR'
              ? 'BEGGING'
              : npc.role === 'QUARRELER'
                ? 'QUARREL'
                : npc.role === 'VAN_VENDOR' || npc.role === 'SHOPKEEPER'
                  ? 'VENDOR_DUTY'
                  : 'PATROL';
    const reply = pickRandomLine(useBengali ? bank.apologyBn : bank.apologyEn);
    return {
      speech: reply,
      mood: 'Calm',
      behavior: nextBehavior,
      healedHp: 0,
      popularityDelta: 4,
      triggerMob: false,
      grantRidePermission: true,
      analysisNote: 'Intent: Apology accepted · Hostility calmed down',
    };
  }

  if (isRideInviteOrRequest) {
    if (npc.role === 'CHANDABAJ') {
      return {
        speech: 'আমি কালা জাহাঙ্গীরের লোক! তোর গাড়িতে উঠব কেন? আগে ফুটপাতের চাঁদা দে!',
        mood: 'Angry',
        behavior: npc.behavior,
        healedHp: 0,
        popularityDelta: 0,
        triggerMob: false,
        grantRidePermission: false,
        analysisNote: 'Intent: Ride Request declined by Chandabaj',
      };
    }
    return {
      speech: npc.speaksEnglishOnly
        ? 'Thank you so much for inviting me! I would love to hop in and ride with you around Baper City!'
        : npc.drivingVehicleId
          ? 'আসেন ভাই, ওঠার অনুমতি দিলাম! আমার গাড়ির পাশের সিটে চড়ে বসুন, গুলশান-শাহবাগ-যাত্রাবাড়ী ঘুরিয়ে আনছি!'
          : 'ধন্যবাদ ভাই! আপনি এত সুন্দর করে ডাকলেন, আমি অবশ্যই আপনার গাড়িতে আপনার পাশে বসে ঘুরব!',
      mood: 'Happy',
      behavior: npc.behavior,
      healedHp: 0,
      popularityDelta: 5,
      triggerMob: false,
      grantRidePermission: true,
      analysisNote: 'Intent: 2-Person Vehicle Permission Granted!',
    };
  }

  if (isSloganOrPolitics) {
    if (npc.role === 'CHANDABAJ') {
      return {
        speech:
          'ওই! আমার সামনে মিছিলের স্লোগান দিবি না! আমরা কালা জাহাঙ্গীরের লোক, চাঁদা না দিলে খবর আছে!',
        mood: 'Angry',
        behavior: 'AGGRO',
        healedHp: 0,
        popularityDelta: 5,
        triggerMob: false,
        grantRidePermission: false,
        analysisNote: 'Intent: Confronted Extortionist with Political Slogan',
      };
    }
    return {
      speech: npc.speaksEnglishOnly
        ? 'I completely agree with you! We all want a safe, peaceful, and extortion-free Baper City!'
        : npc.role === 'POLITICAL_LEADER' || npc.role === 'ACTIVIST'
          ? 'সাবাশ সংগ্রামী ভাই! জয় জনতার জয়! চাঁদাবাজদের কালো হাত—ভেঙে দাও গুঁড়িয়ে দাও! (+জনসমর্থন)'
          : 'ঠিক বলেছেন ভাই! চাঁদাবাজমুক্ত নিরাপদ ঢাকা আমাদের সবার প্রাণের দাবি! (+জনসমর্থন)',
      mood: 'Friendly',
      behavior: npc.behavior,
      healedHp: 0,
      popularityDelta: 8,
      triggerMob: false,
      grantRidePermission: true,
      analysisNote: 'Intent: Joined Political Rally Slogan (+8% Public Support)',
    };
  }

  if (isExtortionDemand) {
    if (npc.role === 'CHANDABAJ') {
      return {
        speech: 'কী?! তুই উল্টো আমার কাছেই চাঁদা চাস?! আয় দেখি কে কত বড় মাস্তান!',
        mood: 'Angry',
        behavior: 'AGGRO',
        healedHp: 0,
        popularityDelta: 0,
        triggerMob: false,
        grantRidePermission: false,
        analysisNote: 'Intent: Rival Extortion Clash',
      };
    }
    return {
      speech: npc.speaksEnglishOnly
        ? 'Excuse me?! How dare you demand extortion money from me! Police and citizens, chase this criminal!'
        : 'এই দেখুন সবাই! নতুন চাঁদাবাজ এসে আমাদের কাছে চাঁদা চাইছে! এলাকাবাসী ও পুলিশ সবাই মিলে ওকে ধাওয়া করুন!',
      mood: 'Angry',
      behavior: 'MOB_CHASE',
      healedHp: 0,
      popularityDelta: -15,
      triggerMob: true,
      grantRidePermission: false,
      analysisNote: 'Intent: Player attempted Extortion · Public Mob Chase Triggered!',
    };
  }

  if (isThreat) {
    const reply = pickRandomLine(useBengali ? bank.threatBn : bank.threatEn);
    if (npc.role === 'CHANDABAJ') {
      return {
        speech: reply,
        mood: 'Angry',
        behavior: 'AGGRO',
        healedHp: 0,
        popularityDelta: 5,
        triggerMob: false,
        grantRidePermission: false,
        analysisNote: 'Intent: Challenged Extortionist',
      };
    }
    return {
      speech: reply,
      mood: 'Angry',
      behavior: npc.role === 'COP' ? 'PURSUIT' : 'MOB_CHASE',
      healedHp: 0,
      popularityDelta: -10,
      triggerMob: true,
      grantRidePermission: false,
      analysisNote: 'Intent: Hostile Threat · Community & Police Alerted',
    };
  }

  if (isTradeOrFood) {
    let healedHp = 0;
    let popularityDelta = 3;
    if (
      npc.role === 'VAN_VENDOR' ||
      npc.role === 'SHOPKEEPER' ||
      npc.role === 'MEDIC' ||
      npc.role === 'NURSE' ||
      npc.role === 'COMMUTER' ||
      npc.role === 'JOGGER'
    ) {
      healedHp = npc.role === 'MEDIC' || npc.role === 'NURSE' ? 35 : 25;
      popularityDelta = 5;
    } else if (npc.role === 'BEGGAR') {
      healedHp = 10;
      popularityDelta = 10;
    }
    const reply = pickRandomLine(useBengali ? bank.tradeBn : bank.tradeEn);
    return {
      speech: reply,
      mood: 'Happy',
      behavior: npc.behavior,
      healedHp,
      popularityDelta,
      triggerMob: false,
      grantRidePermission: true,
      analysisNote:
        npc.role === 'BEGGAR'
          ? 'Intent: Gave Alms to Beggar (+10% Popularity & Blessings)'
          : healedHp > 0
            ? `Intent: Shopping / Medical Aid · Restored +${healedHp} HP`
            : 'Intent: Trade Inquiry',
    };
  }

  if (isCityQuestion) {
    const reply = pickRandomLine(useBengali ? bank.cityInfoBn : bank.cityInfoEn);
    return {
      speech: reply,
      mood: 'Friendly',
      behavior: npc.behavior,
      healedHp: 0,
      popularityDelta: 1,
      triggerMob: false,
      grantRidePermission: true,
      analysisNote: 'Intent: Dhaka City & Community Information shared',
    };
  }

  let healedHp = 0;
  let popularityDelta = 2;
  if ((npc.role === 'MEDIC' || npc.role === 'NURSE') && player.hp < player.maxHp) {
    healedHp = 35;
  } else if (npc.role === 'BEGGAR') {
    popularityDelta = 8;
  }
  const reply = pickRandomLine(useBengali ? bank.greetBn : bank.greetEn);
  return {
    speech: reply,
    mood: npc.role === 'CHANDABAJ' ? 'Suspicious' : 'Friendly',
    mood_unused: undefined,
    behavior: npc.behavior,
    healedHp,
    popularityDelta,
    triggerMob: false,
    grantRidePermission: npc.role !== 'CHANDABAJ',
    analysisNote: 'Intent: Friendly Neighborhood Conversation',
  } as {
    speech: string;
    mood: CharacterMood;
    behavior: CommunityNPCState['behavior'];
    healedHp: number;
    popularityDelta: number;
    triggerMob: boolean;
    grantRidePermission: boolean;
    analysisNote: string;
  };
}
